function updateCaret(){if(!activeFile){$('#editor-position').textContent='Ln 1, Col 1';return}const before=editor.value.slice(0,editor.selectionStart),lines=before.split('\n');$('#editor-position').textContent=`Ln ${lines.length}, Col ${lines.at(-1).length+1}`}
