$('#save-file').onclick=saveEditor;async function saveEditor(){if(!activeFile)return;const t=tabs.get(activeFile);try{await saveTab(t);setEditorStatus(t);renderTabs();toast('Saved '+activeFile.split('/').pop())}catch(e){toast(e.message,true)}}
async function saveTab(t){if(!can('files.write'))throw Error('This account cannot write files.');await api('/api/file?path='+encodeURIComponent(t.path),{method:'PUT',body:t.content});t.saved=t.content;t.dirty=false;if(workspaceRoot)loadSourceControl()}
async function saveAllEditors(){const dirty=[...tabs.values()].filter(t=>t.dirty);if(!dirty.length){toast('All open files are already saved.');return}try{for(const t of dirty)await saveTab(t);if(activeFile&&tabs.has(activeFile))setEditorStatus(tabs.get(activeFile));renderTabs();toast(`Saved ${dirty.length} file${dirty.length===1?'':'s'}.`)}catch(e){if(activeFile&&tabs.has(activeFile))setEditorStatus(tabs.get(activeFile));renderTabs();toast('Save all stopped: '+e.message,true)}}
$('#download-file').onclick=()=>{if(activeFile)location.href='/api/file?download=1&path='+encodeURIComponent(activeFile)};
async function reloadOpenTabs(){for(const [path,t] of tabs){try{const data=await api('/api/file?path='+encodeURIComponent(path));t.content=data.content;t.saved=data.content;t.dirty=false}catch{}}if(activeFile&&tabs.has(activeFile))activateTab(activeFile);renderTabs()}
